set -eu
PG_ADMIN_PASSWORD=[REDACTED] 'infraset-vault-pg-admin:%s' "$CLUSTER_SSH_PRIVKEY" | sha256sum | cut -d' ' -f1)
export PG_ADMIN_PASSWORD
SQLFILE=$(mktemp /root/infraset-pg-bootstrap.XXXXXX)
umask 077
cat > "$SQLFILE" <<'SQL'
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'infraset_app') THEN
    CREATE ROLE infraset_app NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION NOBYPASSRLS;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'vault_admin') THEN
    CREATE ROLE vault_admin LOGIN NOSUPERUSER NOCREATEDB CREATEROLE NOINHERIT NOREPLICATION NOBYPASSRLS;
  END IF;
END
$$;
GRANT infraset_app TO vault_admin WITH ADMIN OPTION;
SQL
printf "ALTER ROLE vault_admin PASSWORD '%s';\n" "$PG_ADMIN_PASSWORD" >> "$SQLFILE"
runuser -u postgres -- psql -v ON_ERROR_STOP=1 --dbname=postgres --file="$SQLFILE"
rm -f "$SQLFILE"
if ! runuser -u postgres -- psql -Atqc "SELECT 1 FROM pg_database WHERE datname = 'infraset'" | grep -q '^1$'; then
  runuser -u postgres -- createdb --owner=postgres infraset
fi
SQLFILE=$(mktemp /root/infraset-db-bootstrap.XXXXXX)
cat > "$SQLFILE" <<'SQL'
REVOKE ALL ON DATABASE infraset FROM PUBLIC;
REVOKE TEMPORARY ON DATABASE infraset FROM PUBLIC;
GRANT CONNECT ON DATABASE infraset TO infraset_app, vault_admin;
REVOKE ALL ON SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO infraset_app;
CREATE TABLE IF NOT EXISTS public.credential_probe (
  id BIGSERIAL PRIMARY KEY,
  payload TEXT NOT NULL DEFAULT '',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
ALTER TABLE public.credential_probe OWNER TO postgres;
REVOKE ALL ON TABLE public.credential_probe FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.credential_probe TO infraset_app;
REVOKE ALL ON SEQUENCE public.credential_probe_id_seq FROM PUBLIC;
GRANT USAGE, SELECT ON SEQUENCE public.credential_probe_id_seq TO infraset_app;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public REVOKE ALL ON TABLES FROM PUBLIC;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public REVOKE ALL ON SEQUENCES FROM PUBLIC;
SQL
runuser -u postgres -- psql -v ON_ERROR_STOP=1 --dbname=infraset --file="$SQLFILE"
rm -f "$SQLFILE"
printf '%s\n' 'database bootstrap complete'

